CREATE DATABASE IF NOT EXISTS nearride CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nearride;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) UNIQUE NOT NULL,email VARCHAR(190) UNIQUE NULL,password_hash VARCHAR(255),google_id VARCHAR(190) UNIQUE,full_name VARCHAR(120) NOT NULL,avatar_url VARCHAR(500),phone VARCHAR(30),whatsapp_number VARCHAR(30),is_customer BOOLEAN DEFAULT TRUE,is_provider BOOLEAN DEFAULT FALSE,is_admin BOOLEAN DEFAULT FALSE,is_phone_verified BOOLEAN DEFAULT FALSE,is_email_verified BOOLEAN DEFAULT FALSE,account_status ENUM('active','suspended','deleted') DEFAULT 'active',last_login_at DATETIME,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS provider_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NOT NULL,display_name VARCHAR(120) NOT NULL,provider_type ENUM('vehicle_owner','driver','both') NOT NULL,description TEXT,identity_verification_status ENUM('not_submitted','pending','verified','rejected') DEFAULT 'not_submitted',average_rating DECIMAL(3,2) DEFAULT 0,total_ratings INT UNSIGNED DEFAULT 0,completed_profile BOOLEAN DEFAULT FALSE,is_available BOOLEAN DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicle_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(80) UNIQUE NOT NULL,icon_name VARCHAR(80),is_active BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) UNIQUE NOT NULL,provider_id BIGINT UNSIGNED NOT NULL,category_id INT UNSIGNED,listing_type ENUM('vehicle_with_driver','vehicle_without_driver','driver_only') NOT NULL,title VARCHAR(160) NOT NULL,description TEXT,manufacturer VARCHAR(100),model VARCHAR(100),manufactured_year SMALLINT,registration_number_encrypted TEXT,registration_number_masked VARCHAR(30),driver_license_number_encrypted TEXT,driver_license_number_masked VARCHAR(30),passenger_capacity SMALLINT UNSIGNED,load_capacity_kg DECIMAL(10,2),fuel_type VARCHAR(40),transmission_type VARCHAR(40),has_air_conditioning BOOLEAN DEFAULT FALSE,available_now BOOLEAN DEFAULT FALSE,long_distance_available BOOLEAN DEFAULT FALSE,emergency_contact_available BOOLEAN DEFAULT FALSE,minimum_hire_hours DECIMAL(6,2),starting_price DECIMAL(12,2),price_unit ENUM('per_km','per_hour','per_day','fixed','negotiable') DEFAULT 'negotiable',price_negotiable BOOLEAN DEFAULT TRUE,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,public_area_name VARCHAR(160),service_radius_km SMALLINT UNSIGNED DEFAULT 25,phone VARCHAR(30) NOT NULL,whatsapp_number VARCHAR(30),preferred_contact_method ENUM('phone','whatsapp','both') DEFAULT 'both',status ENUM('draft','pending','active','paused','rejected','expired','deleted') DEFAULT 'draft',moderation_note VARCHAR(500),view_count INT UNSIGNED DEFAULT 0,contact_click_count INT UNSIGNED DEFAULT 0,expires_at DATETIME,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME,FOREIGN KEY(provider_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES vehicle_categories(id),INDEX idx_geo(latitude,longitude),INDEX idx_filters(status,category_id,listing_type,available_now,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listing_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,image_url VARCHAR(500) NOT NULL,thumbnail_url VARCHAR(500) NOT NULL,sort_order TINYINT UNSIGNED DEFAULT 0,created_at DATETIME NOT NULL,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listing_availability (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,day_of_week TINYINT UNSIGNED NOT NULL,start_time TIME,end_time TIME,is_available BOOLEAN DEFAULT TRUE,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS favourites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY unique_favourite(user_id,listing_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listing_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,reporter_user_id BIGINT UNSIGNED NOT NULL,reason ENUM('incorrect_information','fraud','unsafe_vehicle','offensive_content','duplicate','unavailable','other') NOT NULL,description VARCHAR(1000),status ENUM('pending','reviewed','resolved','dismissed') DEFAULT 'pending',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(listing_id) REFERENCES listings(id),FOREIGN KEY(reporter_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listing_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED,event_type ENUM('view','phone_click','whatsapp_click','favourite') NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(listing_id) REFERENCES listings(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refresh_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash VARCHAR(255) NOT NULL,device_name VARCHAR(160),expires_at DATETIME NOT NULL,revoked_at DATETIME,created_at DATETIME NOT NULL,INDEX(token_hash),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
INSERT IGNORE INTO vehicle_categories(name,slug,icon_name,sort_order,created_at,updated_at) VALUES ('Motorbike','motorbike','two_wheeler',1,NOW(),NOW()),('Three Wheeler','three-wheeler','electric_rickshaw',2,NOW(),NOW()),('Car','car','directions_car',3,NOW(),NOW()),('SUV','suv','directions_car',4,NOW(),NOW()),('Van','van','airport_shuttle',5,NOW(),NOW()),('Bus','bus','directions_bus',6,NOW(),NOW()),('Pickup','pickup','local_shipping',7,NOW(),NOW()),('Lorry','lorry','local_shipping',8,NOW(),NOW()),('Tow Vehicle','tow-vehicle','car_repair',9,NOW(),NOW()),('Tractor','tractor','agriculture',10,NOW(),NOW()),('Other','other','commute',11,NOW(),NOW());
